// Imports — public tools, primitive definitions and reusable orchestration.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
import {
  extendedOscillator as extendedOscillatorDefinition,
  gain as gainDefinition,
  mixer9 as mixer9Definition,
} from '@manifold/author/primitives';
import { GraphContractError, createGraphWorkspace, createLiveGraphSession } from '@manifold/author';
import { chooseMainVoice } from '@manifold/author/examples/main-voice-control';
import { oscillatorPreviewCurves } from '@manifold/author/examples/oscillator-preview';
import { adsr as adsrDefinition } from '@manifold/author/primitives';

// Reusable graph definition — inspect and edit the authored voice factory below.
const OSC_BASE = '/midi/synth/rack/osc/1';
const hz = (note) => 440 * 2 ** ((note - 69) / 12);
const voicePath = (index) => `${OSC_BASE}/voice/${index}`;
const oscillatorPath = (index) => `${OSC_BASE}/nodes/${index === 9 ? 'manual' : `voice_${index}`}`;
/** Add the original eight voices, manual voice, nine-input mixer, and output gain. */
function addRackOscillatorModule(
  graph,
  { firstVoiceId = 4, mixerId = 13, outputId = 21, connectOutput = false } = {},
) {
  const oscillators = [];
  for (let index = 1; index <= 9; index++) {
    const oscillator = graph.add(extendedOscillatorDefinition.type, {
      id: firstVoiceId + index - 1,
    });
    graph.registerInstance(oscillatorPath(index), oscillator);
    oscillator.parameter('waveform').set(1);
    oscillator.parameter('frequency').set(index === 9 ? hz(60) : 220);
    oscillator.parameter('level').set(0);
    if (index <= 8) oscillator.parameter('retriggerOnLevelRise').set(1);
    oscillators.push(oscillator);
  }
  const mixer = graph.add(mixer9Definition.type, { id: mixerId });
  graph.registerInstance(`${OSC_BASE}/nodes/mixer`, mixer);
  for (let index = 0; index < oscillators.length; index++) {
    graph.connect(oscillators[index].output('out'), mixer.input(`in-${index + 1}`));
  }
  const output = graph.add(gainDefinition.type, { id: outputId });
  graph.registerInstance(`${OSC_BASE}/nodes/output`, output);
  output.parameter('level').set(0.2);
  graph.connect(mixer.output('out'), output.input('audio'));
  if (connectOutput) graph.connect(output.output('out'), graph.output.input('in'));
  for (const [suffix, range] of Object.entries({
    waveform: { min: 0, max: 7, default: 1, discrete: true },
    drive: { min: 0, max: 20, default: 0 },
    driveShape: { min: 0, max: 3, default: 0, discrete: true },
    driveBias: { min: -1, max: 1, default: 0 },
    pulseWidth: { min: 0.01, max: 0.99, default: 0.5 },
    unison: { min: 1, max: 8, default: 1, discrete: true },
    detune: { min: 0, max: 100, default: 0 },
    spread: { min: 0, max: 1, default: 0 },
    renderMode: { min: 0, max: 1, default: 0, discrete: true },
    additivePartials: { min: 1, max: 32, default: 8, discrete: true },
    additiveTilt: { min: -1, max: 1, default: 0 },
    additiveDrift: { min: 0, max: 1, default: 0 },
    manualPitch: { min: 0, max: 127, default: 60 },
    manualLevel: { min: 0, max: 1, default: 0 },
    output: { min: 0, max: 2, default: 0.8 },
  }))
    graph.registerControl(`${OSC_BASE}/${suffix}`, range);
  for (let index = 1; index <= 8; index++) {
    for (const [suffix, range] of Object.entries({
      gate: { min: 0, max: 1, default: 0 },
      vOct: { min: 0, max: 127, default: 60 },
      fm: { min: -1, max: 1, default: 0 },
      pwCv: { min: 0, max: 1, default: 0.5 },
    }))
      graph.registerControl(`${voicePath(index)}/${suffix}`, range);
  }
  return output;
}
// Graph definition — construct inspectable primitives with stable identities.
function buildGraph() {
  const graph = createGraphWorkspace();
  addRackOscillatorModule(graph, { connectOutput: true });
  return graph;
}
/** Interpret old path controls against any prepared graph containing this module. */
function setRackOscillatorControl(session, path, value) {
  const project = session.toProject();
  const values = new Map(project.controls.map((entry) => [entry.path, entry.value]));
  if (!values.has(path))
    throw new GraphContractError('unknown-control', `Unknown oscillator control: ${path}`);
  const instances = new Map(project.instances.map((entry) => [entry.path, entry.nodeId]));
  const node = (index) => instances.get(oscillatorPath(index));
  const output = instances.get(`${OSC_BASE}/nodes/output`);
  if (!output || Array.from({ length: 9 }, (_, index) => node(index + 1)).some((id) => !id)) {
    throw new GraphContractError('unsupported-project', 'Rack oscillator nodes are missing');
  }
  const suffix = path.slice(path.lastIndexOf('/') + 1);
  const control = { path, value };
  if (suffix === 'output')
    return session.parameterWithControl({ nodeId: output, id: 0, value: value * 0.25 }, control);
  if (suffix === 'manualPitch')
    return session.parameterWithControl(
      {
        nodeId: node(9),
        id: 1,
        value: Math.max(20, Math.min(8000, hz(value))),
      },
      control,
    );
  if (suffix === 'manualLevel')
    return session.parameterWithControl({ nodeId: node(9), id: 2, value: value * 0.4 }, control);
  const match = path.match(/\/voice\/(\d+)\/(gate|vOct|fm|pwCv)$/);
  if (match) {
    const index = Number(match[1]);
    const base = voicePath(index);
    const get = (key) => (key === suffix ? value : values.get(`${base}/${key}`));
    const edit =
      suffix === 'gate'
        ? {
            nodeId: node(index),
            id: 2,
            value: Math.min(0.4, Math.max(0, value)),
          }
        : suffix === 'pwCv'
          ? {
              nodeId: node(index),
              id: 4,
              value: Math.max(
                0.01,
                Math.min(0.99, values.get(`${OSC_BASE}/pulseWidth`) + value - 0.5),
              ),
            }
          : {
              nodeId: node(index),
              id: 1,
              value: Math.max(20, Math.min(8000, hz(get('vOct') + get('fm') * 12))),
            };
    return session.parameterWithControl(edit, control);
  }
  const ids = {
    waveform: 0,
    drive: 5,
    driveShape: 6,
    driveBias: 7,
    pulseWidth: 4,
    unison: 10,
    detune: 11,
    spread: 12,
    renderMode: 13,
    additivePartials: 14,
    additiveTilt: 15,
    additiveDrift: 16,
  };
  if (Object.hasOwn(ids, suffix)) {
    const edits = Array.from({ length: 9 }, (_, index) => ({
      nodeId: node(index + 1),
      id: ids[suffix],
      value:
        suffix === 'pulseWidth' && index < 8
          ? Math.max(0.01, Math.min(0.99, value + values.get(`${voicePath(index + 1)}/pwCv`) - 0.5))
          : value,
    }));
    return session.parametersWithControl(edits, control);
  }
  throw new GraphContractError('unknown-control', `Unsupported oscillator control: ${path}`);
}
// Host integration — the session publishes edits only after audio acceptance.

export default function createProject() {
  // Audio interface and composition — host input/output are graph boundaries.
  const graph = createGraphWorkspace();
  addRackOscillatorModule(graph, { connectOutput: true });
  // Eight reusable core envelopes, composed through the public graph contract.
  for (let index = 1; index <= 8; index++) {
    const envelope = graph.add(adsrDefinition.type, { id: 30 + index });
    graph.registerInstance(OSC_BASE + '/envelopes/' + index, envelope);
    const input = graph.find(13).input('in-' + index);
    graph.disconnect(input);
    graph.connect(graph.find(3 + index).output('out'), envelope.input('audio'));
    graph.connect(envelope.output('out'), input);
  }
  const ADSR_BASE = '/keyboard/adsr';
  for (const [name, min, max, value] of [
    ['attack', 0.001, 5, 0.05],
    ['decay', 0.001, 5, 0.2],
    ['sustain', 0, 1, 0.7],
    ['release', 0.001, 10, 0.4],
  ])
    graph.registerControl(ADSR_BASE + '/' + name, { min, max, default: value });
  const control = (name, label, group, choices) => ({
    id: name,
    type: 'control',
    path: OSC_BASE + '/' + name,
    label,
    group,
    ...(choices ? { choices } : {}),
  });
  // Presentation — one declared UI serves retained and immediate renderers.
  const view = [
    {
      id: 'oscillator-preview',
      type: 'curve',
      points: [],
      label: 'WAVE MODE',
      color: '#38bdf8',
      group: 'Preview',
    },
    {
      id: 'drive-preview',
      type: 'curve',
      points: [],
      label: 'DRIVE',
      color: '#f97316',
      group: 'Preview',
    },
    control('waveform', 'Waveform', 'Source', [
      'Sine',
      'Saw',
      'Square',
      'Triangle',
      'Blend',
      'Noise',
      'Pulse',
      'SuperSaw',
    ]),
    control('pulseWidth', 'Pulse width', 'Source'),
    control('drive', 'Drive', 'Source'),
    control('driveShape', 'Drive shape', 'Source', ['Soft', 'Hard', 'Clip', 'Fold']),
    control('driveBias', 'Bias', 'Source'),
    control('unison', 'Unison', 'Unison'),
    control('detune', 'Detune (cents)', 'Unison'),
    control('spread', 'Stereo spread', 'Unison'),
    control('renderMode', 'Render mode', 'Additive', ['Standard', 'Additive']),
    control('additivePartials', 'Partials', 'Additive'),
    control('additiveTilt', 'Tilt', 'Additive'),
    control('additiveDrift', 'Drift', 'Additive'),
    control('manualPitch', 'Pitch (MIDI)', 'Manual'),
    control('manualLevel', 'Level', 'Manual'),
    control('output', 'Output', 'Manual'),
    ...['attack', 'decay', 'sustain', 'release'].map((name) => ({
      id: name,
      type: 'control',
      path: ADSR_BASE + '/' + name,
      label: name[0].toUpperCase() + name.slice(1),
      group: 'ADSR',
    })),
    { id: 'keyboard', type: 'keyboard', firstNote: 48, noteCount: 25, group: 'Play' },
  ];
  let previewKey = '',
    previewModel;
  function paint(ui, snapshot) {
    const controls = Object.fromEntries(
      snapshot.graph.controls
        .filter((c) => c.path.startsWith(OSC_BASE + '/'))
        .map((c) => [c.path.slice(OSC_BASE.length + 1), c.value]),
    );
    const key = JSON.stringify(
      [
        'waveform',
        'pulseWidth',
        'renderMode',
        'additivePartials',
        'additiveTilt',
        'additiveDrift',
        'drive',
        'driveShape',
        'driveBias',
      ].map((k) => controls[k]),
    );
    if (key !== previewKey) {
      previewKey = key;
      previewModel = oscillatorPreviewCurves(controls);
    }
    const preview = previewModel;
    for (const { path, type, ...options } of view) {
      if (type === 'curve')
        ui.curve({
          ...options,
          points: options.id === 'drive-preview' ? preview.drive : preview.wave,
          color: options.id === 'drive-preview' ? '#f97316' : preview.color,
          label: options.id === 'drive-preview' ? 'DRIVE' : preview.label,
        });
      else if (type === 'keyboard')
        ui.keyboard({
          ...options,
          activeNotes: (snapshot.eventState?.voices ?? []).filter((v) => v.gate).map((v) => v.note),
        });
      else ui.control(path, options);
    }
  }
  // Live controls — the host invokes this mapper for accepted UI gestures.
  function onControl(session, path, value) {
    if (path.startsWith(ADSR_BASE + '/')) {
      const id = ['attack', 'decay', 'sustain', 'release'].indexOf(path.split('/').at(-1));
      return session.parametersWithControl(
        Array.from({ length: 8 }, (_, i) => ({ nodeId: 31 + i, id, value })),
        { path, value },
      );
    }
    return setRackOscillatorControl(session, path, value);
  }
  // Live events — keyboard/MIDI enter through the returned onEvent hook.
  const eventStateSchema = 'manifold.rack-oscillator.keyboard.v1';
  const envelopeId = (index) => 31 + index;
  const startVoice = (session, index, note, amplitude) => {
    setRackOscillatorControl(session, voicePath(index + 1) + '/vOct', note);
    setRackOscillatorControl(session, voicePath(index + 1) + '/gate', amplitude);
  };
  const releaseVoice = (session, index) =>
    session.parameters([{ nodeId: envelopeId(index), id: 4, value: 0 }]);
  const silenceVoice = (session, index) =>
    setRackOscillatorControl(session, voicePath(index + 1) + '/gate', 0);

  // Allocation is project orchestration; envelopes and oscillator samples run in Rust.
  const emptyVoice = () => ({
    active: false,
    note: null,
    gate: 0,
    stamp: 0,
    owner: '',
    channel: 0,
    startedAt: 0,
    releasedAt: 0,
    releaseLevel: 0,
    velocity: 0,
    keyDown: 0,
    envelopeStage: 'idle',
    envelopeLevel: 0,
  });
  const eventState = { stamp: 0, sustain: {}, voices: Array.from({ length: 8 }, emptyVoice) };
  function onEvent(session, event, state) {
    const project = session.toProject(),
      controls = new Map(project.controls.map((c) => [c.path, c.value]));
    const get = (name) => controls.get(ADSR_BASE + '/' + name);
    const owner = String(event.owner ?? 'user'),
      channel = event.channel ?? 0;
    if (!Number.isInteger(channel) || channel < 0 || channel > 15)
      throw new GraphContractError('invalid-event', 'Invalid MIDI channel');
    const next = structuredClone(state);
    for (const voice of next.voices) {
      const age = Math.max(0, event.at - voice.startedAt);
      if (voice.gate) {
        voice.envelopeLevel =
          age < get('attack')
            ? age / get('attack')
            : age < get('attack') + get('decay')
              ? 1 - ((1 - get('sustain')) * (age - get('attack'))) / get('decay')
              : get('sustain');
        voice.envelopeStage = 'sustain';
      } else if (voice.active) {
        voice.envelopeLevel =
          voice.releaseLevel * Math.max(0, 1 - (event.at - voice.releasedAt) / get('release'));
        voice.envelopeStage = voice.envelopeLevel > 0 ? 'release' : 'idle';
        if (voice.envelopeStage === 'idle') voice.active = false;
      }
    }
    if (event.type === 'panic') {
      for (const [index, voice] of next.voices.entries()) {
        if (
          (event.owner == null || voice.owner === owner) &&
          (event.channel == null || voice.channel === channel)
        ) {
          silenceVoice(session, index);
          session.parameters([{ nodeId: envelopeId(index), id: 4, value: 0 }]);
          next.voices[index] = emptyVoice();
        }
      }
      for (const key of Object.keys(next.sustain)) {
        const separator = key.lastIndexOf(':');
        if (
          (event.owner == null || key.slice(0, separator) === owner) &&
          (event.channel == null || Number(key.slice(separator + 1)) === channel)
        )
          delete next.sustain[key];
      }
      return next;
    }
    if (event.type === 'all-notes-off') {
      for (const [index, voice] of next.voices.entries()) {
        if (voice.gate && voice.owner === owner && voice.channel === channel) {
          voice.keyDown = 0;
          if (next.sustain?.[owner + ':' + channel]) continue;
          releaseVoice(session, index);
          voice.gate = 0;
          voice.releasedAt = event.at;
          voice.releaseLevel = voice.envelopeLevel;
          voice.envelopeStage = 'release';
        }
      }
      return next;
    }
    if (event.type === 'sustain') {
      if (typeof event.down !== 'boolean')
        throw new GraphContractError('invalid-event', 'Sustain must be boolean');
      next.sustain ??= {};
      next.sustain[owner + ':' + channel] = event.down;
      if (!event.down)
        for (const [index, voice] of next.voices.entries()) {
          if (voice.gate && !voice.keyDown && voice.owner === owner && voice.channel === channel) {
            releaseVoice(session, index);
            voice.gate = 0;
            voice.releasedAt = event.at;
            voice.releaseLevel = voice.envelopeLevel;
            voice.envelopeStage = 'release';
          }
        }
      return next;
    }
    if (
      !['note-on', 'note-off'].includes(event.type) ||
      !Number.isInteger(event.note) ||
      event.note < 0 ||
      event.note > 127
    )
      throw new GraphContractError('invalid-event', 'Expected a MIDI note-on, note-off or panic');
    if (event.type === 'note-on') {
      const velocity = event.velocity ?? 100;
      if (!Number.isInteger(velocity) || velocity < 1 || velocity > 127)
        throw new GraphContractError('invalid-event', 'Invalid note velocity');
      const index = chooseMainVoice(next.voices),
        stamp = (next.stamp % 1000000) + 1;
      startVoice(session, index, event.note, Math.min(0.4, 0.03 + (velocity / 127) * 0.37));
      session.parameters([
        { nodeId: envelopeId(index), id: 4, value: 1 },
        { nodeId: envelopeId(index), id: 5, value: stamp },
      ]);
      next.stamp = stamp;
      next.voices[index] = {
        ...emptyVoice(),
        active: true,
        note: event.note,
        gate: 1,
        stamp,
        owner,
        channel,
        startedAt: event.at,
        velocity,
        keyDown: 1,
        envelopeStage: 'attack',
      };
    } else
      for (const [index, voice] of next.voices.entries()) {
        if (
          voice.gate &&
          voice.note === event.note &&
          voice.owner === owner &&
          voice.channel === channel
        ) {
          voice.keyDown = 0;
          if (next.sustain?.[owner + ':' + channel]) continue;
          releaseVoice(session, index);
          voice.gate = 0;
          voice.releasedAt = event.at;
          voice.releaseLevel = voice.envelopeLevel;
          voice.envelopeStage = 'release';
        }
      }
    return next;
  }

  return { graph, view, paint, onControl, onEvent, eventState, eventStateSchema };
}
